/** 拆分后的全拼数组（模块加载时一次解析，之后索引 O(1)）。 */
export const HAN_PINYINS: readonly string[] = TABLE_PARTS.join("\n").split("\n");

/** 取一个汉字的全拼；非 CJK 基本区返回空串。 */
export function pinyinOf(ch: string): string {
  const cp = ch.codePointAt(0);
  return cp === undefined || cp < HAN_START || cp > 0x9fa5 ? "" : HAN_PINYINS[cp - HAN_START] ?? "";
}
